import {copyHTML,copyRaw} from './site-copy.js';
import {backend} from './backend.js';
let stats=null,failed=false;
export async function trackVisit(){try{let id=localStorage.getItem('lexamah:visitor-id');if(!id){id=crypto.randomUUID();localStorage.setItem('lexamah:visitor-id',id);}await backend.trackVisit(id);}catch{/* Tracking does not block studying. */}}
export async function loadStats(){try{stats=await backend.adminStats();failed=false;}catch{failed=true;}}
export function statsCards(){if(failed)return `<div class="notice">${copyHTML("analytics.4199c6ab66fd")}</div>`;if(!stats)return '';const n=value=>Math.max(0,Number(value)||0).toLocaleString();return `<div class="section-title"><h2>${copyHTML("analytics.247e0b62560a")}</h2></div><div class="stats">${[[stats.visitors_7d,copyRaw("analytics.a0eea9d26af8"),copyRaw("analytics.9f056f2f0928")],[stats.registered_users,copyRaw("analytics.1fc779e778b4"),copyRaw("analytics.4d2df5129231")],[stats.active_users_7d,copyRaw("analytics.b8f1c407dff0"),copyRaw("analytics.1ee28f78d2ba")],[stats.downloads,copyRaw("analytics.37af42fa8436"),copyRaw("analytics.a1cb8212a4cf")]].map(([value,label,description])=>`<div class="stat"><div><small>${label}</small><strong>${n(value)}</strong><span class="sub">${description}</span></div></div>`).join('')}</div>`;}
